    if(preg_match('/roulette|fortuna|фортуна|рулетк|excursion|экскурсион/ui',$name.' '.$original))return null;
    return['operator_key'=>$operator,'native_hotel_id'=>(string)$native,'andromeda_hotel_id'=>$id,'country_id'=>$country,'hotel_name'=>mb_substr($name,0,512),'original_name'=>mb_substr($original,0,512),'town'=>is_string($r['town']??null)?mb_substr($r['town'],0,200):null,'operator_name'=>is_string($r['operator']??null)?mb_substr($r['operator'],0,200):null,'is_operator_hotel_key'=>false,'action'=>'price','request_sha256'=>$request,'response_sha256'=>$response,'source'=>'live_price_mass'];
}
