        $stateCountry=[];foreach($stateCounts as $sk=>$counts){arsort($counts,SORT_NUMERIC);$cid=(int)array_key_first($counts);$sum=array_sum($counts);if(isset($core[$cid])&&$counts[$cid]>=2&&$counts[$cid]/$sum>=0.90)$stateCountry[$sk]=$cid;}
