        foreach($pending as $r){$id=(string)$r['external_hotel_id'];if(!preg_match('/^[1-9][0-9]{0,19}$/D',$id)){$skipped['invalid_id']=($skipped['invalid_id']??0)+1;continue;}$e=mcr_evidence((string)$r['evidence_json']);$sk=mcr_state_key($e);if($sk===null||!preg_match('/^[1-9][0-9]{0,9}$/D',(string)$sk)){$skipped['missing_state']=($skipped['missing_state']??0)+1;continue;}$cid=$stateCountry[(string)$sk]??null;$country=mcr_country_name($e);if($cid===null&&$country!==null)$cid=$coreKeys[mcr_country_key($country)]??null;if($cid===null||!isset($core[$cid])){$skipped['non_core_or_unresolved_country']=($skipped['non_core_or_unresolved_country']??0)+1;continue;}$names=mcr_names($e);$queue[]=['andromeda_hotel_id'=>$id,'state_key'=>(int)$sk,'country_id'=>(int)$cid,'country_name'=>$core[$cid],'frequency'=>mcr_frequency($e),'name'=>$names[0]??null,'evidence_sha256'=>(string)$r['evidence_sha256']];}
